<?php
namespace App\Domain\Notifications\Services; use App\Domain\Notifications\Models\{UserNotification,NotificationPreference}; use App\Models\User; use Illuminate\Support\Str;
class NotificationService { public function create(User $u,string $type,string $title,string $body,?string $url=null,array $metadata=[]):UserNotification{$dedupe=$metadata['dedupe_key']??null;if($dedupe&&($existing=UserNotification::where('user_id',$u->id)->where('metadata_json->dedupe_key',$dedupe)->first()))return $existing;return UserNotification::create(['user_id'=>$u->id,'type'=>$type,'title'=>$title,'body'=>$body,'action_url'=>$url,'metadata_json'=>$metadata,'created_at'=>now()]);} public function paginate(User $u,int $perPage=25){return UserNotification::where('user_id',$u->id)->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->latest('created_at')->paginate($perPage);} public function markRead(User $u,int $id):UserNotification{$n=UserNotification::where(['id'=>$id,'user_id'=>$u->id])->firstOrFail();$n->update(['read_at'=>$n->read_at??now()]);return $n->refresh();} public function markAllRead(User $u):int{return UserNotification::where('user_id',$u->id)->whereNull('read_at')->update(['read_at'=>now()]);} public function ensurePreferences(User $u):NotificationPreference{return NotificationPreference::firstOrCreate(['user_id'=>$u->id],['unsubscribe_token'=>Str::random(64)]);} }
